  INDEX `idx_patient_id`(`resident_id` ASC) USING BTREE,
  INDEX `idx_disease_code`(`condition_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '患者既往病史表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_resident_health_history
-- ----------------------------

-- ----------------------------
-- Table structure for biz_risk_assessment
-- ----------------------------
DROP TABLE IF EXISTS `biz_risk_assessment`;
CREATE TABLE `biz_risk_assessment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `resident_id` bigint NOT NULL,
  `assessment_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评估时间',
  `assessment_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `health_history_score` decimal(5, 2) NULL DEFAULT NULL,
  `health_check_score` decimal(5, 2) NULL DEFAULT NULL,
  `vital_signs_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '生命体征风险评分',
  `questionnaire_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '问卷调查风险评分',
  `fall_risk` decimal(5, 2) NULL DEFAULT NULL,
  `pressure_sore_risk` decimal(5, 2) NULL DEFAULT NULL,
  `nutrition_risk` decimal(5, 2) NULL DEFAULT NULL,
  `cognitive_risk` decimal(5, 2) NULL DEFAULT NULL,
  `wandering_risk` decimal(5, 2) NULL DEFAULT NULL,
  `depression_risk` decimal(5, 2) NULL DEFAULT NULL,
  `self_harm_risk` decimal(5, 2) NULL DEFAULT NULL,
  `neglect_risk` decimal(5, 2) NULL DEFAULT NULL,
  `total_score` decimal(5, 2) NOT NULL COMMENT '总风险评分',
  `risk_level` enum('LOW','MEDIUM','HIGH','CRITICAL') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '风险等级',
  `confidence_level` decimal(5, 2) NULL DEFAULT NULL COMMENT '预测置信度',
  `risk_factors` json NULL COMMENT '主要风险因素',
  `protective_factors` json NULL COMMENT '保护性因素',
  `recommendations` json NULL COMMENT '护理建议',
  `sent_to_resident` tinyint NULL DEFAULT 0,
  `sent_time` datetime NULL DEFAULT NULL COMMENT '发送时间',
  `sent_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发送人',
  `scale_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '量表类型 FALL/PRESSURE/VTE/STROKE',
  `suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评估建议',
  `evaluator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评估人姓名',
  `assessed_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评估人员',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `health_predictions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '健康状况预测JSON',
  `assessment_breakdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '六模块综合评估得分、权重和数据依据JSON',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_assessment`(`resident_id` ASC, `assessment_time` ASC) USING BTREE,
  INDEX `idx_risk_level`(`risk_level` ASC) USING BTREE,
  INDEX `idx_assessment_type`(`assessment_type` ASC) USING BTREE,
  INDEX `idx_sent_to_patient`(`sent_to_resident` ASC) USING BTREE,
  INDEX `idx_patient_sent`(`resident_id` ASC, `sent_to_resident` ASC) USING BTREE,
  INDEX `idx_scale_type`(`scale_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风险评估结果表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_risk_assessment
-- ----------------------------

-- ----------------------------
-- Table structure for biz_risk_model_parameters
-- ----------------------------
DROP TABLE IF EXISTS `biz_risk_model_parameters`;
CREATE TABLE `biz_risk_model_parameters`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型名称',
  `model_version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型版本',
  `parameter_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '参数名称',
  `parameter_value` decimal(10, 6) NOT NULL COMMENT '参数值',
  `parameter_type` enum('WEIGHT','THRESHOLD','COEFFICIENT') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '参数类型',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '参数描述',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_model_param`(`model_name` ASC, `model_version` ASC, `parameter_name` ASC) USING BTREE,
  INDEX `idx_model_active`(`model_name` ASC, `is_active` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风险预测模型参数表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_risk_model_parameters
-- ----------------------------

-- ----------------------------
-- Table structure for biz_risk_record
-- ----------------------------
DROP TABLE IF EXISTS `biz_risk_record`;
CREATE TABLE `biz_risk_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `resident_id` bigint NOT NULL,
  `evaluator_id` bigint NULL DEFAULT NULL COMMENT '评估人ID',
  `evaluator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '评估人姓名',
  `scale_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '量表类型(FALL/VTE/PRESSURE)',
  `total_score` int NOT NULL COMMENT '总分',
  `risk_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '风险等级(LOW/MEDIUM/HIGH)',
  `detail_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '答题详情JSON',
  `evaluate_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评估时间',
  `sent_to_resident` tinyint NULL DEFAULT 0,
  `sent_time` datetime NULL DEFAULT NULL COMMENT '发送时间',
  `sent_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发送人',
  `suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '评估建议',
  `request_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PC' COMMENT '评估来源: PC-电脑端, MINIPROGRAM-小程序',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_id`(`resident_id` ASC) USING BTREE,
  INDEX `idx_scale_type`(`scale_type` ASC) USING BTREE,
  INDEX `idx_evaluate_time`(`evaluate_time` ASC) USING BTREE,
  INDEX `idx_sent_to_patient`(`sent_to_resident` ASC) USING BTREE,
  INDEX `idx_patient_sent`(`resident_id` ASC, `sent_to_resident` ASC) USING BTREE,
  INDEX `idx_request_source`(`request_source` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 125 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '风险评估记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_risk_record
-- ----------------------------

-- ----------------------------
-- Table structure for biz_scale_def
-- ----------------------------
DROP TABLE IF EXISTS `biz_scale_def`;
CREATE TABLE `biz_scale_def`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `scale_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '量表类型',
  `scale_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '量表名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '量表描述',
  `questions_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '题目配置JSON',
  `scoring_rules_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '评分规则JSON',
  `risk_levels_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '风险等级配置JSON',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用',
  `version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'v1.0' COMMENT '版本号',
  `assessment_weight` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '养老量表模块内部权重百分比',
  `creator_id` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `creator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_scale_type`(`scale_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量表定义表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_scale_def
-- ----------------------------

-- ----------------------------
-- Table structure for biz_scale_question
-- ----------------------------
DROP TABLE IF EXISTS `biz_scale_question`;
CREATE TABLE `biz_scale_question`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `scale_id` bigint NOT NULL COMMENT '所属量表ID',
  `question_order` int NOT NULL COMMENT '题目序号',
  `question_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '题目内容',
  `question_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '题目类型：radio/checkbox/input/select',
  `options_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '选项配置JSON',
  `required` tinyint(1) NULL DEFAULT 1 COMMENT '是否必填：1-必填，0-选填',
  `weight` decimal(5, 2) NULL DEFAULT 1.00 COMMENT '题目权重',
  `group_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '题目分组',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_scale_id`(`scale_id` ASC) USING BTREE,
  INDEX `idx_question_order`(`question_order` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '量表题目表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_scale_question
-- ----------------------------

-- ----------------------------
-- Table structure for biz_visit_appointment
-- ----------------------------
DROP TABLE IF EXISTS `biz_visit_appointment`;
CREATE TABLE `biz_visit_appointment`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `resident_id` bigint NOT NULL COMMENT '老人ID',
  `resident_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '老人姓名',
  `visitor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '探访人姓名',
  `visitor_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '探访人电话',
  `visitor_relation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '与老人关系',
  `visit_date` date NOT NULL COMMENT '探访日期',
  `visit_start_time` time NULL DEFAULT NULL COMMENT '探访开始时间',
  `visit_end_time` time NULL DEFAULT NULL COMMENT '探访结束时间',
  `visitor_count` int NULL DEFAULT 1 COMMENT '探访人数',
  `special_notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '特殊备注',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT '状态(PENDING-待确认/APPROVED-已批准/REJECTED-已拒绝/CANCELLED-已取消/COMPLETED-已完成)',
  `approved_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批人',
  `approve_time` datetime NULL DEFAULT NULL COMMENT '审批时间',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '拒绝原因',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_resident_id`(`resident_id` ASC) USING BTREE,
  INDEX `idx_visit_date`(`visit_date` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 79 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '家属探访预约表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of biz_visit_appointment
-- ----------------------------

-- ----------------------------
-- Table structure for biz_vital_signs
-- ----------------------------
DROP TABLE IF EXISTS `biz_vital_signs`;
CREATE TABLE `biz_vital_signs`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `resident_id` bigint NOT NULL,
  `resident_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `room_bed_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `care_zone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `record_date` date NULL DEFAULT NULL COMMENT '记录日期',
  `record_time` time NULL DEFAULT NULL COMMENT '记录时间',
  `measurement_time` datetime NOT NULL COMMENT '测量时间',
  `measurement_type` enum('ROUTINE','CONTINUOUS','EMERGENCY') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ROUTINE' COMMENT '测量类型',
  `systolic_pressure` int NULL DEFAULT NULL COMMENT '收缩压(原字段)',
  `diastolic_pressure` int NULL DEFAULT NULL COMMENT '舒张压(原字段)',
  `systolic_bp` decimal(5, 1) NULL DEFAULT NULL COMMENT '收缩压(mmHg)',
  `diastolic_bp` decimal(5, 1) NULL DEFAULT NULL COMMENT '舒张压(mmHg)',
  `heart_rate` decimal(5, 1) NULL DEFAULT NULL COMMENT '心率(次/分)',
  `respiratory_rate` decimal(5, 1) NULL DEFAULT NULL COMMENT '呼吸频率(次/分)',
  `temperature` decimal(4, 1) NULL DEFAULT NULL COMMENT '体温(℃)',
  `oxygen_saturation` decimal(5, 2) NULL DEFAULT NULL COMMENT '血氧饱和度(%)',
  `blood_oxygen` decimal(5, 2) NULL DEFAULT NULL COMMENT '血氧(原字段名)',
  `mean_arterial_pressure` decimal(5, 1) NULL DEFAULT NULL COMMENT '平均动脉压(mmHg)',
  `pulse_pressure` decimal(5, 1) NULL DEFAULT NULL COMMENT '脉压差(mmHg)',
  `respiratory_depth` enum('SHALLOW','NORMAL','DEEP') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '呼吸深度',
  `respiratory_rhythm` enum('REGULAR','IRREGULAR') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '呼吸节律',
  `weight` decimal(5, 2) NULL DEFAULT NULL COMMENT '体重(kg)',
  `blood_glucose` decimal(5, 2) NULL DEFAULT NULL COMMENT '血糖(mmol/L)',
  `bp_variability` decimal(8, 2) NULL DEFAULT NULL COMMENT '血压变异性',
  `hr_variability` decimal(8, 2) NULL DEFAULT NULL COMMENT '心率变异性',
  `measured_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '测量人员',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注(原字段名)',
  `recorder_id` bigint NULL DEFAULT NULL COMMENT '记录人ID',
  `recorder_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录人姓名',
  `recorder_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录人类型',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_time`(`resident_id` ASC, `measurement_time` ASC) USING BTREE,
  INDEX `idx_measurement_type`(`measurement_type` ASC) USING BTREE,
  INDEX `idx_record_date`(`record_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '生命体征监测表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_vital_signs
-- ----------------------------

-- ----------------------------
-- Table structure for care_notifications
-- ----------------------------
DROP TABLE IF EXISTS `care_notifications`;
CREATE TABLE `care_notifications`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '通知ID',
  `care_manager_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `resident_id` bigint NOT NULL,
  `resident_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `care_zone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `notification_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知类型',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知内容',
  `extra_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外数据JSON',
  `is_read` tinyint(1) NULL DEFAULT 0 COMMENT '是否已读',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `read_time` datetime NULL DEFAULT NULL COMMENT '阅读时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_doctor_id`(`care_manager_id` ASC) USING BTREE,
  INDEX `idx_patient_id`(`resident_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_is_read`(`is_read` ASC) USING BTREE,
  INDEX `idx_department`(`care_zone` ASC) USING BTREE,
  INDEX `idx_type_department`(`notification_type` ASC, `care_zone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '医生通知表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of care_notifications
-- ----------------------------

-- ----------------------------
-- Table structure for legacy_appointment
-- ----------------------------
DROP TABLE IF EXISTS `legacy_appointment`;
CREATE TABLE `legacy_appointment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '患者姓名',
  `doctor_id` bigint NOT NULL COMMENT '医生ID',
  `doctor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '医生姓名',
  `department` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预约科室',
  `appointment_date` date NOT NULL COMMENT '预约日期',
  `time_slot` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预约时段(如08:00-08:30)',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '就诊原因',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT '状态(PENDING:待确认, CONFIRMED:已确认, DIAGNOSED:已诊断, ARRANGED:已安排, COMPLETED:已完成, CANCELLED:已取消)',
  `diagnosis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '病情判断',
  `diagnosis_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '病情等级(MILD:轻症, MODERATE:中症, SEVERE:重症, CRITICAL:危重)',
  `arranged_department` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '安排科室',
  `arranged_bed_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '安排床位号',
  `arrange_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '安排备注',
  `diagnose_time` datetime NULL DEFAULT NULL COMMENT '诊断时间',
  `arrange_time` datetime NULL DEFAULT NULL COMMENT '安排时间',
  `cancel_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取消原因',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_id`(`patient_id` ASC) USING BTREE,
  INDEX `idx_doctor_id`(`doctor_id` ASC) USING BTREE,
  INDEX `idx_appointment_date`(`appointment_date` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预约记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of legacy_appointment
-- ----------------------------

-- ----------------------------
-- Table structure for legacy_care_task
-- ----------------------------
DROP TABLE IF EXISTS `legacy_care_task`;
CREATE TABLE `legacy_care_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务类型：评估/复评/干预',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '患者姓名',
  `bed_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '床号',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务描述',
  `priority` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'NORMAL' COMMENT '优先级：HIGH/NORMAL/LOW',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态：0-待办，1-已完成',
  `assignee_id` bigint NULL DEFAULT NULL COMMENT '负责人ID',
  `assignee_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '负责人姓名',
  `due_time` datetime NULL DEFAULT NULL COMMENT '截止时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_id`(`patient_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_assignee_id`(`assignee_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '任务管理表' ROW_FORMAT = DYNAMIC;

