-- ----------------------------
-- Table structure for legacy_health_check_results
-- ----------------------------
DROP TABLE IF EXISTS `legacy_health_check_results`;
CREATE TABLE `legacy_health_check_results`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `test_date` datetime NOT NULL COMMENT '检查日期时间',
  `test_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检查类别',
  `wbc_count` decimal(8, 2) NULL DEFAULT NULL COMMENT '白细胞计数(×10^9/L)',
  `hemoglobin` decimal(8, 2) NULL DEFAULT NULL COMMENT '血红蛋白(g/L)',
  `platelet_count` decimal(8, 2) NULL DEFAULT NULL COMMENT '血小板计数(×10^9/L)',
  `rbc_count` decimal(8, 2) NULL DEFAULT NULL COMMENT '红细胞计数(×10^12/L)',
  `hematocrit` decimal(5, 2) NULL DEFAULT NULL COMMENT '红细胞压积(%)',
  `glucose` decimal(8, 2) NULL DEFAULT NULL COMMENT '血糖(mmol/L)',
  `alt` decimal(8, 2) NULL DEFAULT NULL COMMENT '丙氨酸转氨酶(U/L)',
  `ast` decimal(8, 2) NULL DEFAULT NULL COMMENT '天冬氨酸转氨酶(U/L)',
  `bilirubin_total` decimal(8, 2) NULL DEFAULT NULL COMMENT '总胆红素(μmol/L)',
  `creatinine` decimal(8, 2) NULL DEFAULT NULL COMMENT '肌酐(μmol/L)',
  `urea` decimal(8, 2) NULL DEFAULT NULL COMMENT '尿素(mmol/L)',
  `sodium` decimal(8, 2) NULL DEFAULT NULL COMMENT '钠(mmol/L)',
  `potassium` decimal(8, 2) NULL DEFAULT NULL COMMENT '钾(mmol/L)',
  `chloride` decimal(8, 2) NULL DEFAULT NULL COMMENT '氯(mmol/L)',
  `pt` decimal(8, 2) NULL DEFAULT NULL COMMENT '凝血酶原时间(秒)',
  `aptt` decimal(8, 2) NULL DEFAULT NULL COMMENT '活化部分凝血活酶时间(秒)',
  `inr` decimal(8, 3) NULL DEFAULT NULL COMMENT '国际标准化比值',
  `fibrinogen` decimal(8, 2) NULL DEFAULT NULL COMMENT '纤维蛋白原(g/L)',
  `crp` decimal(8, 2) NULL DEFAULT NULL COMMENT 'C反应蛋白(mg/L)',
  `pct` decimal(8, 3) NULL DEFAULT NULL COMMENT '降钙素原(ng/mL)',
  `esr` decimal(8, 2) NULL DEFAULT NULL COMMENT '红细胞沉降率(mm/h)',
  `troponin_i` decimal(8, 3) NULL DEFAULT NULL COMMENT '肌钙蛋白I(ng/mL)',
  `ck_mb` decimal(8, 2) NULL DEFAULT NULL COMMENT '肌酸激酶同工酶(U/L)',
  `ck` decimal(8, 2) NULL DEFAULT NULL COMMENT '肌酸激酶(U/L)',
  `albumin` decimal(8, 2) NULL DEFAULT NULL COMMENT '白蛋白(g/L)',
  `prealbumin` decimal(8, 2) NULL DEFAULT NULL COMMENT '前白蛋白(mg/L)',
  `total_protein` decimal(8, 2) NULL DEFAULT NULL COMMENT '总蛋白(g/L)',
  `reference_range` json NULL COMMENT '参考范围',
  `abnormal_flags` json NULL COMMENT '异常标记',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_test_date`(`patient_id` ASC, `test_date` ASC) USING BTREE,
  INDEX `idx_test_category`(`test_category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实验室检查结果表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of legacy_health_check_results
-- ----------------------------

-- ----------------------------
-- Table structure for legacy_health_report
-- ----------------------------
DROP TABLE IF EXISTS `legacy_health_report`;
CREATE TABLE `legacy_health_report`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '患者姓名',
  `bed_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '床位号',
  `department` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '科室',
  `symptom_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '症状类型(pain/nausea/fever/dizzy/breath/sleep/appetite/other)',
  `symptom_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '症状名称',
  `severity` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '严重程度(mild/moderate/severe)',
  `severity_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '严重程度名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '症状描述',
  `location` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '症状部位',
  `start_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '开始时间',
  `triggers` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '诱发因素(逗号分隔)',
  `additional_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '其他信息',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT '状态(PENDING:待处理, HANDLING:处理中, HANDLED:已处理)',
  `handler_id` bigint NULL DEFAULT NULL COMMENT '处理护士ID',
  `handler_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '处理护士姓名',
  `handle_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '处理结果/回复',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_id`(`patient_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '症状上报表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of legacy_health_report
-- ----------------------------

-- ----------------------------
-- Table structure for legacy_intervention
-- ----------------------------
DROP TABLE IF EXISTS `legacy_intervention`;
CREATE TABLE `legacy_intervention`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `risk_record_id` bigint NULL DEFAULT NULL COMMENT '关联的风险评估记录ID',
  `intervention_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '干预类型',
  `intervention_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '干预内容',
  `executor_id` bigint NULL DEFAULT NULL COMMENT '执行人ID',
  `executor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '执行人姓名',
  `execute_time` datetime NULL DEFAULT NULL COMMENT '执行时间',
  `effect` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '干预效果',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_id`(`patient_id` ASC) USING BTREE,
