-- ----------------------------
-- Table structure for legacy_medication_reminder
-- ----------------------------
DROP TABLE IF EXISTS `legacy_medication_reminder`;
CREATE TABLE `legacy_medication_reminder`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `medication_id` bigint NOT NULL COMMENT '用药记录ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `medication_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '药品名称',
  `dosage` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '剂量',
  `reminder_date` date NOT NULL COMMENT '提醒日期',
  `reminder_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '提醒时间(HH:mm)',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT '状态(PENDING:待服用, TAKEN:已服用, SKIPPED:已跳过, MISSED:已错过)',
  `taken_time` datetime NULL DEFAULT NULL COMMENT '实际服用时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_medication_id`(`medication_id` ASC) USING BTREE,
  INDEX `idx_patient_id`(`patient_id` ASC) USING BTREE,
  INDEX `idx_reminder_date`(`reminder_date` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用药提醒表' ROW_FORMAT = DYNAMIC;

