-- ----------------------------
DROP TABLE IF EXISTS `legacy_resident_assessment_status`;
CREATE TABLE `legacy_resident_assessment_status`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `patient_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '患者姓名',
  `bed_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '床号',
  `gender` tinyint NULL DEFAULT NULL COMMENT '性别 1-男 2-女',
  `age` int NULL DEFAULT NULL COMMENT '年龄',
  `diagnosis` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '诊断',
  `admission_time` datetime NULL DEFAULT NULL COMMENT '入院日期',
  `assessment_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING' COMMENT '评估状态: PENDING-待评估, COMPLETED-已评估, CANCELLED-已取消',
  `request_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'MINIPROGRAM' COMMENT '评估来源: MINIPROGRAM-小程序, PC-电脑端',
  `request_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请评估时间',
  `request_doctor_id` bigint NULL DEFAULT NULL COMMENT '申请医生ID',
  `request_doctor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请医生姓名',
  `assessment_time` datetime NULL DEFAULT NULL COMMENT '评估完成时间',
  `assessor_id` bigint NULL DEFAULT NULL COMMENT '评估人ID',
  `assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '评估人姓名',
  `assessment_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '评估结果JSON',
  `is_discharged` tinyint NULL DEFAULT 0 COMMENT '是否已出院 0-否 1-是',
  `discharge_date` datetime NULL DEFAULT NULL COMMENT '出院日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除 0-未删除 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_patient_id`(`patient_id` ASC) USING BTREE,
  INDEX `idx_assessment_status`(`assessment_status` ASC) USING BTREE,
  INDEX `idx_request_time`(`request_time` ASC) USING BTREE,
  INDEX `idx_is_discharged`(`is_discharged` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '患者评估状态表' ROW_FORMAT = DYNAMIC;

